var original=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<VRC.SDK3.Avatars.Components.VRCAvatarDescriptor>(true)).Single(a=>a.name=="MANUKA_lilToon");var avatar=UnityEngine.Object.Instantiate(original.gameObject);var helpers=new System.Collections.Generic.List<UnityEngine.GameObject>();var meshes=new System.Collections.Generic.List<UnityEngine.Mesh>();
try{var colliders=new System.Collections.Generic.List<UnityEngine.MeshCollider>();foreach(var renderer in avatar.GetComponentsInChildren<UnityEngine.SkinnedMeshRenderer>(true).Where(r=>r.name=="Body"||r.name=="Manuka_body")){var mesh=new UnityEngine.Mesh();meshes.Add(mesh);renderer.BakeMesh(mesh,true);var helper=new UnityEngine.GameObject("profile");helpers.Add(helper);helper.transform.SetPositionAndRotation(renderer.transform.position,renderer.transform.rotation);helper.transform.localScale=renderer.transform.lossyScale;var col=helper.AddComponent<UnityEngine.MeshCollider>();col.sharedMesh=mesh;colliders.Add(col);}UnityEngine.Physics.SyncTransforms();var result=new System.Collections.Generic.List<string>();foreach(float y in new[]{1.035f,1.04755f,1.06f,1.075f,1.085f,1.10f}){var front=new System.Collections.Generic.List<float>();var back=new System.Collections.Generic.List<float>();foreach(var col in colliders){if(col.Raycast(new UnityEngine.Ray(new UnityEngine.Vector3(0,y,.3f),UnityEngine.Vector3.back),out var f,.6f))front.Add(f.point.z);if(col.Raycast(new UnityEngine.Ray(new UnityEngine.Vector3(0,y,-.3f),UnityEngine.Vector3.forward),out var b,.6f))back.Add(b.point.z);}result.Add(y+";front="+string.Join(",",front)+";back="+string.Join(",",back));}return result;}finally{foreach(var h in helpers)UnityEngine.Object.DestroyImmediate(h);foreach(var m in meshes)UnityEngine.Object.DestroyImmediate(m);UnityEngine.Object.DestroyImmediate(avatar);}
